/**
 * PassageNavigation Component
 * Controls: Testament Filter (All, OT, NT), Book Dropdown, Chapter Dropdown, Verse Dropdown,
 * and Previous/Next Chapter navigation buttons.
 */

function PassageNavigation({
  testamentFilter = "all",
  onSelectTestament,
  booksList = [],
  selectedBook = "genesis",
  onSelectBook,
  selectedChapter = 1,
  onChangeChapter,
  selectedVerse = "all",
  onChangeVerse,
  totalChapters = 50,
  totalVerses = 31,
  onPrevChapter,
  onNextChapter
}) {
  // Filter books list according to testament filter
  const filteredBooks = React.useMemo(() => {
    if (testamentFilter === "all") return booksList;
    return booksList.filter((b) => b.testament === testamentFilter);
  }, [booksList, testamentFilter]);

  // Generate array for chapters
  const chaptersArray = React.useMemo(() => {
    const count = totalChapters || 1;
    return Array.from({ length: count }, (_, i) => i + 1);
  }, [totalChapters]);

  // Generate array for verses
  const versesArray = React.useMemo(() => {
    const count = totalVerses || 31;
    return Array.from({ length: count }, (_, i) => i + 1);
  }, [totalVerses]);

  return (
    <section className="passage-navigation-bar" aria-label="Scripture Passage Selectors">
      {/* Left Selectors Group */}
      <div className="nav-selectors-cluster">
        {/* Testament Filter Pills */}
        <div className="testament-filter-pills" role="radiogroup" aria-label="Filter testament">
          <button
            type="button"
            className={`btn-testament-pill ${testamentFilter === "all" ? "active" : ""}`}
            onClick={() => onSelectTestament("all")}
          >
            All
          </button>
          <button
            type="button"
            className={`btn-testament-pill ${testamentFilter === "OT" ? "active" : ""}`}
            onClick={() => onSelectTestament("OT")}
          >
            OT (పాత నిబంధన)
          </button>
          <button
            type="button"
            className={`btn-testament-pill ${testamentFilter === "NT" ? "active" : ""}`}
            onClick={() => onSelectTestament("NT")}
          >
            NT (కొత్త నిబంధన)
          </button>
        </div>

        {/* Book Dropdown Selector */}
        <div className="custom-select-container book-select-container">
          <select
            className="passage-select book-dropdown"
            value={selectedBook}
            onChange={(e) => onSelectBook(e.target.value)}
            aria-label="Select Bible Book"
          >
            {filteredBooks.map((b) => (
              <option key={b.slug} value={b.slug}>
                {b.name} ({b.teluguName})
              </option>
            ))}
          </select>
          <span className="select-arrow-icon">▼</span>
        </div>

        {/* Chapter Dropdown Selector */}
        <div className="custom-select-container chapter-select-container">
          <select
            className="passage-select chapter-dropdown"
            value={selectedChapter}
            onChange={(e) => onChangeChapter(Number(e.target.value))}
            aria-label="Select Chapter Number"
          >
            {chaptersArray.map((ch) => (
              <option key={ch} value={ch}>
                {ch}
              </option>
            ))}
          </select>
          <span className="select-arrow-icon">▼</span>
        </div>

        {/* Verse Dropdown Selector */}
        <div className="custom-select-container verse-select-container">
          <select
            className="passage-select verse-dropdown"
            value={selectedVerse}
            onChange={(e) => onChangeVerse(e.target.value)}
            aria-label="Select Verse"
          >
            <option value="all">All</option>
            {versesArray.map((v) => (
              <option key={v} value={v}>
                {v}
              </option>
            ))}
          </select>
          <span className="select-arrow-icon">▼</span>
        </div>
      </div>

      {/* Right Navigation Arrows */}
      <div className="nav-buttons-cluster">
        <button
          type="button"
          className="btn-nav-prev"
          onClick={onPrevChapter}
          disabled={selectedChapter <= 1}
          title="Previous chapter"
        >
          <span className="nav-arrow">&lt;</span>
          <span>Previous</span>
        </button>

        <button
          type="button"
          className="btn-nav-next"
          onClick={onNextChapter}
          title="Next chapter"
        >
          <span>Next</span>
          <span className="nav-arrow">&gt;</span>
        </button>
      </div>
    </section>
  );
}

window.PassageNavigation = PassageNavigation;

/**
 * ScriptureReader Component
 * Renders Scripture reading area matching the design:
 * Header with open-book badge, Book title, Telugu name, KJV & verses badges,
 * and individual verses with circular numbers and search/bookmark/copy controls.
 */

function ScriptureReader({
  chapterData,
  selectedLang = "kjv",
  fontSize = 18,
  selectedVerse = "all",
  bookmarkedVerses = [],
  onToggleBookmark,
  onCopyVerse,
  onSearchVerse
}) {
  if (!chapterData) {
    return (
      <div className="reader-loading-card">
        <p>Loading Scripture passage...</p>
      </div>
    );
  }

  const { book, chapter, verses = [], totalVerses = 31 } = chapterData;
  const isTelugu = selectedLang === "telugu";

  // Filter verses if a specific verse is selected in dropdown
  const displayedVerses = React.useMemo(() => {
    if (selectedVerse === "all" || !selectedVerse) return verses;
    return verses.filter((v) => String(v.verse) === String(selectedVerse));
  }, [verses, selectedVerse]);

  return (
    <article 
      className="scripture-reader-card" 
      aria-label="Scripture Chapter Reading Area"
      style={{ "--verse-font-size": `${fontSize}px` }}
    >
      {/* Chapter Card Header */}
      <header className="reader-card-header">
        <div className="chapter-title-cluster">
          {/* Circular Open Book Badge */}
          <div className="reader-book-circle-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path>
              <path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path>
            </svg>
          </div>

          <div className="chapter-names-meta">
            <h1 className="chapter-primary-heading">
              {book.name} {chapter}
            </h1>
            <p className="chapter-secondary-subheading">
              <span className="telugu-subname">{book.teluguName}</span>
              <span className="subheading-bullet">•</span>
              <span className="subheading-chapter-label">Chapter {chapter}</span>
            </p>
          </div>
        </div>

        {/* Translation & Count Badges */}
        <div className="reader-meta-badges">
          <span className="badge-navy-translation">
            {selectedLang.toUpperCase()}
          </span>
          <span className="badge-verse-total">
            {totalVerses} verses
          </span>
        </div>
      </header>

      {/* Verses List */}
      <div className="reader-verses-list">
        {displayedVerses.map((v) => {
          const verseNumber = v.verse;
          const isBookmarked = bookmarkedVerses.includes(verseNumber);
          const verseText = isTelugu ? v.telugu : v.kjv;

          return (
            <div 
              key={verseNumber} 
              id={`verse-${verseNumber}`}
              className={`verse-row-container ${isBookmarked ? "bookmarked-row" : ""}`}
            >
              {/* Circular Verse Number Badge */}
              <div className="verse-badge-col">
                <span className="verse-number-circle">{verseNumber}</span>
              </div>

              {/* Verse Text */}
              <div className="verse-text-col">
                <p className={`verse-text-content ${isTelugu ? "telugu-font" : ""}`}>
                  {verseText}
                </p>
              </div>

              {/* Action Controls: Search, Bookmark, Copy */}
              <div className="verse-controls-col" aria-label={`Controls for verse ${verseNumber}`}>
                {/* Search Button */}
                <button
                  type="button"
                  className="btn-verse-control btn-verse-search"
                  onClick={() => onSearchVerse && onSearchVerse({
                    book,
                    chapter,
                    verse: verseNumber,
                    text: verseText
                  })}
                  title="Search related verses"
                  aria-label={`Search related verses for verse ${verseNumber}`}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="11" cy="11" r="8"></circle>
                    <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
                  </svg>
                </button>

                {/* Bookmark Button */}
                <button
                  type="button"
                  className={`btn-verse-control btn-verse-bookmark ${isBookmarked ? "bookmarked" : ""}`}
                  onClick={() => onToggleBookmark && onToggleBookmark(verseNumber)}
                  title={isBookmarked ? "Remove bookmark" : "Bookmark this verse"}
                  aria-label={isBookmarked ? "Remove bookmark" : "Bookmark this verse"}
                >
                  <svg viewBox="0 0 24 24" fill={isBookmarked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"></path>
                  </svg>
                </button>

                {/* Copy Button */}
                <button
                  type="button"
                  className="btn-verse-control btn-verse-copy"
                  onClick={() => onCopyVerse && onCopyVerse({
                    book,
                    chapter,
                    verse: verseNumber,
                    text: verseText
                  })}
                  title="Copy verse to clipboard"
                  aria-label={`Copy verse ${verseNumber} to clipboard`}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                  </svg>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </article>
  );
}

window.ScriptureReader = ScriptureReader;

/**
 * SearchPanel Component
 * Provides full-text keyword search UI, testament filter, and mock search results cards.
 */

function SearchPanel({ onNavigateToVerse, initialQuery = "" }) {
  const [query, setQuery] = React.useState(initialQuery || "beginning");
  const [testament, setTestament] = React.useState("all");
  const [results, setResults] = React.useState(window.MOCK_SEARCH_RESULTS || []);

  const handleSearch = (e) => {
    if (e) e.preventDefault();
    if (!query.trim()) {
      setResults([]);
      return;
    }
    // Filter mock results for UI demonstration
    const filtered = (window.MOCK_SEARCH_RESULTS || []).filter((r) =>
      r.text.toLowerCase().includes(query.toLowerCase()) ||
      r.reference.toLowerCase().includes(query.toLowerCase())
    );
    setResults(filtered.length > 0 ? filtered : window.MOCK_SEARCH_RESULTS || []);
  };

  return (
    <section className="search-panel-card" aria-label="Bible Search Panel">
      <div className="search-controls-header">
        <form className="search-form-row" onSubmit={handleSearch}>
          <div className="search-input-field-wrap">
            <span className="search-lens-icon">🔍</span>
            <input
              type="text"
              className="search-text-input"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by keyword, topic, or reference (e.g. light, grace, Genesis 1:1)..."
              aria-label="Scripture search query"
            />
            {query && (
              <button
                type="button"
                className="btn-clear-search-text"
                onClick={() => setQuery("")}
                aria-label="Clear search input"
              >
                ✕
              </button>
            )}
          </div>

          <div className="custom-select-container search-testament-select">
            <select
              value={testament}
              onChange={(e) => setTestament(e.target.value)}
              aria-label="Filter search testament"
            >
              <option value="all">Entire Bible (అన్ని గ్రంథాలు)</option>
              <option value="ot">Old Testament (పాత నిబంధన)</option>
              <option value="nt">New Testament (కొత్త నిబంధన)</option>
            </select>
            <span className="select-arrow-icon">▼</span>
          </div>

          <button type="submit" className="btn-search-action">
            <span>Search</span>
          </button>
        </form>
      </div>

      {/* Results Section */}
      <div className="search-results-area">
        <div className="search-meta-bar">
          <span className="search-count-label">
            Found {results.length} passage{results.length === 1 ? "" : "s"} for &ldquo;{query}&rdquo;
          </span>
        </div>

        <div className="search-cards-grid">
          {results.map((item, index) => (
            <div key={index} className="search-result-card">
              <div className="search-result-header">
                <span className="result-ref-title">{item.reference}</span>
                <span className="result-telugu-ref">({item.teluguReference})</span>
                <span className="result-trans-badge">{item.translation}</span>
              </div>
              <p className="result-verse-text">&ldquo;{item.text}&rdquo;</p>
              <div className="search-result-actions">
                <button
                  type="button"
                  className="btn-result-navigate"
                  onClick={() => onNavigateToVerse && onNavigateToVerse("genesis", 1, 1)}
                >
                  Read Chapter &gt;
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

window.SearchPanel = SearchPanel;

/**
 * Main BibleApp Component
 * Connects Sidebar, TopBar, DailyVerseHero, ViewTabs, PassageNavigation, ScriptureReader,
 * SearchPanel, BookmarksPanel, and OfflinePanel using React functional components and Hooks.
 */

function BibleApp() {
  // Navigation & View State
  const [activeTab, setActiveTab] = React.useState("reader");
  const [selectedLang, setSelectedLang] = React.useState("kjv");
  const [testamentFilter, setTestamentFilter] = React.useState("all");
  const [selectedBook, setSelectedBook] = React.useState("genesis");
  const [selectedChapter, setSelectedChapter] = React.useState(1);
  const [selectedVerse, setSelectedVerse] = React.useState("all");

  // Typography & Aesthetics State
  const [fontSize, setFontSize] = React.useState(18);
  const [theme, setTheme] = React.useState("light");
  const [mobileSidebarOpen, setMobileSidebarOpen] = React.useState(false);

  // Search & Bookmarks State
  const [searchQuery, setSearchQuery] = React.useState("");
  const [bookmarks, setBookmarks] = React.useState(window.MOCK_BOOKMARKS || []);
  const [toastMessage, setToastMessage] = React.useState("");

  // Sync theme with document element
  React.useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
  }, [theme]);

  // Derived bookmarked verse numbers for Genesis 1
  const bookmarkedVerses = React.useMemo(() => {
    return bookmarks
      .filter((b) => b.bookSlug === selectedBook && b.chapter === selectedChapter)
      .map((b) => b.verse);
  }, [bookmarks, selectedBook, selectedChapter]);

  // Toast feedback helper
  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => {
      setToastMessage("");
    }, 2400);
  };

  // Font Size Controls
  const handleIncreaseFontSize = () => {
    setFontSize((prev) => Math.min(28, prev + 2));
  };

  const handleDecreaseFontSize = () => {
    setFontSize((prev) => Math.max(14, prev - 2));
  };

  // Theme Toggle
  const handleToggleTheme = () => {
    setTheme((prev) => (prev === "light" ? "dark" : "light"));
  };

  // Chapter Navigation
  const handlePrevChapter = () => {
    if (selectedChapter > 1) {
      setSelectedChapter((prev) => prev - 1);
      setSelectedVerse("all");
    }
  };

  const handleNextChapter = () => {
    setSelectedChapter((prev) => prev + 1);
    setSelectedVerse("all");
  };

  // Bookmark Toggle
  const handleToggleBookmark = (verseNum) => {
    const isBookmarked = bookmarkedVerses.includes(verseNum);
    if (isBookmarked) {
      setBookmarks((prev) =>
        prev.filter((b) => !(b.bookSlug === selectedBook && b.chapter === selectedChapter && b.verse === verseNum))
      );
      showToast(`Removed bookmark for Verse ${verseNum}`);
    } else {
      const verseObj = (window.MOCK_GENESIS_CHAPTER_1.verses || []).find((v) => v.verse === verseNum);
      const newBm = {
        id: `${selectedBook}-${selectedChapter}-${verseNum}`,
        bookSlug: selectedBook,
        bookName: "Genesis",
        bookTeluguName: "ఆదికాండము",
        chapter: selectedChapter,
        verse: verseNum,
        translation: selectedLang.toUpperCase(),
        text: selectedLang === "telugu" ? (verseObj?.telugu || "") : (verseObj?.kjv || ""),
        savedAt: "Just now"
      };
      setBookmarks((prev) => [newBm, ...prev]);
      showToast(`★ Bookmarked Genesis ${selectedChapter}:${verseNum}`);
    }
  };

  const handleRemoveBookmark = (verseNum) => {
    setBookmarks((prev) =>
      prev.filter((b) => !(b.bookSlug === selectedBook && b.chapter === selectedChapter && b.verse === verseNum))
    );
    showToast(`Bookmark removed`);
  };

  // Copy Verse
  const handleCopyVerse = (item) => {
    const textToCopy = `“${item.text}” — ${item.book.name} ${item.chapter}:${item.verse} (${selectedLang.toUpperCase()})`;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(textToCopy).then(() => {
        showToast("✓ Copied verse to clipboard!");
      }).catch(() => {
        showToast("Copied: " + item.book.name + " " + item.chapter + ":" + item.verse);
      });
    } else {
      showToast("✓ Copied verse to clipboard!");
    }
  };

  // Search Verse Jump
  const handleSearchVerse = (item) => {
    setSearchQuery(item.text.slice(0, 30));
    setActiveTab("search");
  };

  // Navigate directly to passage
  const handleNavigateToPassage = (bookSlug, chapter, verse = "all") => {
    setSelectedBook(bookSlug || "genesis");
    setSelectedChapter(chapter || 1);
    setSelectedVerse(verse || "all");
    setActiveTab("reader");
    window.scrollTo({ top: 380, behavior: "smooth" });
  };

  return (
    <div className="bible-app-root">
      {/* Toast Notification */}
      {toastMessage && (
        <div className="bible-toast-notification" role="status">
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Left Sidebar */}
      <window.Sidebar
        activeTab={activeTab}
        onSelectTab={setActiveTab}
        bookmarksCount={bookmarks.length}
        isOpen={mobileSidebarOpen}
        onClose={() => setMobileSidebarOpen(false)}
      />

      {/* Main Content Area */}
      <main className="bible-main-layout">
        {/* Top Right Utility Bar */}
        <window.TopBar
          selectedLang={selectedLang}
          onChangeLang={setSelectedLang}
          fontSize={fontSize}
          onIncreaseFontSize={handleIncreaseFontSize}
          onDecreaseFontSize={handleDecreaseFontSize}
          theme={theme}
          onToggleTheme={handleToggleTheme}
          onToggleSidebar={() => setMobileSidebarOpen((prev) => !prev)}
        />

        {/* Verse of the Day Hero Banner */}
        <window.DailyVerseHero
          dailyVerse={window.MOCK_DAILY_VERSE}
          selectedLang={selectedLang}
          onReadChapter={handleNavigateToPassage}
        />

        {/* View Tabs Bar: Read Scripture, Search Bible, Bookmarks, Offline Reading */}
        <window.ViewTabs
          activeTab={activeTab}
          onSelectTab={setActiveTab}
          bookmarksCount={bookmarks.length}
        />

        {/* READER VIEW */}
        {activeTab === "reader" && (
          <>
            {/* Passage Filter and Dropdown Bar */}
            <window.PassageNavigation
              testamentFilter={testamentFilter}
              onSelectTestament={setTestamentFilter}
              booksList={window.MOCK_BOOKS || []}
              selectedBook={selectedBook}
              onSelectBook={setSelectedBook}
              selectedChapter={selectedChapter}
              onChangeChapter={setSelectedChapter}
              selectedVerse={selectedVerse}
              onChangeVerse={setSelectedVerse}
              totalChapters={50}
              totalVerses={31}
              onPrevChapter={handlePrevChapter}
              onNextChapter={handleNextChapter}
            />

            {/* Scripture Reading Area */}
            <window.ScriptureReader
              chapterData={window.MOCK_GENESIS_CHAPTER_1}
              selectedLang={selectedLang}
              fontSize={fontSize}
              selectedVerse={selectedVerse}
              bookmarkedVerses={bookmarkedVerses}
              onToggleBookmark={handleToggleBookmark}
              onCopyVerse={handleCopyVerse}
              onSearchVerse={handleSearchVerse}
            />
          </>
        )}

        {/* SEARCH VIEW */}
        {activeTab === "search" && (
          <window.SearchPanel
            initialQuery={searchQuery}
            onNavigateToVerse={handleNavigateToPassage}
          />
        )}

        {/* BOOKMARKS VIEW */}
        {activeTab === "bookmarks" && (
          <window.BookmarksPanel
            bookmarks={bookmarks}
            onRemoveBookmark={handleRemoveBookmark}
            onNavigateToVerse={handleNavigateToPassage}
            onCopyVerse={handleCopyVerse}
          />
        )}

        {/* OFFLINE VIEW */}
        {activeTab === "offline" && (
          <window.OfflinePanel />
        )}
      </main>
    </div>
  );
}

window.BibleApp = BibleApp;

/* ==========================================================================
   Grace Church Bible - React Frontend UI Design System
   Matches uploaded screenshot with extreme visual fidelity.
