  display: none;
}

.tabs-flex-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-view-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 18px;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  position: relative;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-view-tab:hover:not(.active) {
  color: var(--text-navy);
  background: var(--bg-hover);
}

.btn-view-tab.active {
  color: var(--accent-blue);
  background: var(--accent-blue-light);
  font-weight: 600;
}

.tab-icon-wrapper {
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.tab-icon-svg {
  width: 17px;
  height: 17px;
}

.tab-badge-pill {
  background: var(--bg-subtle);
  color: var(--text-muted);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 1px 7px;
  border-radius: var(--radius-full);
}

.btn-view-tab.active .tab-badge-pill {
  background: rgba(37, 99, 235, 0.15);
  color: var(--accent-blue);
}

.tab-active-indicator-bar {
  position: absolute;
  bottom: 0;
  left: 12px;
  right: 12px;
  height: 2.5px;
  background: var(--accent-blue);
  border-radius: 2px;
}

/* ==========================================================================
   Passage Navigation & Filter Bar
   ========================================================================== */
.passage-navigation-bar {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 22px;
  box-shadow: var(--shadow-xs);
}

.nav-selectors-cluster {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

/* Testament Filter Buttons */
.testament-filter-pills {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.btn-testament-pill {
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-page);
  border: 1px solid var(--border-subtle);
  transition: var(--transition);
}

.btn-testament-pill:hover:not(.active) {
  color: var(--text-navy);
  background: var(--bg-hover);
}

.btn-testament-pill.active {
  background: #0f1e36;
  color: #ffffff;
  border-color: #0f1e36;
}

[data-theme="dark"] .btn-testament-pill.active {
  background: #1e3a8a;
  border-color: #1e3a8a;
}

/* Custom Select Dropdowns */
.custom-select-container {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.passage-select {
  appearance: none;
  -webkit-appearance: none;
  background: var(--bg-page);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 7px 30px 7px 12px;
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  outline: none;
  transition: var(--transition);
}

.passage-select:hover {
  border-color: #cbd5e1;
  color: var(--text-navy);
}

.passage-select:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 2px var(--accent-blue-light);
}

.select-arrow-icon {
  position: absolute;
  right: 10px;
  font-size: 0.65rem;
  color: var(--text-muted);
  pointer-events: none;
}

.book-dropdown {
  min-width: 170px;
}

.chapter-dropdown {
  min-width: 60px;
}

.verse-dropdown {
  min-width: 65px;
}

/* Prev / Next Navigation Buttons */
.nav-buttons-cluster {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-nav-prev {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-page);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  padding: 7px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.84rem;
  font-weight: 600;
  transition: var(--transition);
}

.btn-nav-prev:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-nav-prev:not(:disabled):hover {
  color: var(--text-navy);
  border-color: #cbd5e1;
}

.btn-nav-next {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #0f1e36;
  color: #ffffff;
  padding: 7px 18px;
  border-radius: var(--radius-sm);
  font-size: 0.84rem;
  font-weight: 600;
  transition: var(--transition);
}

.btn-nav-next:hover {
  background: #1e293b;
  transform: translateY(-1px);
}

[data-theme="dark"] .btn-nav-next {
  background: #1e3a8a;
}

[data-theme="dark"] .btn-nav-next:hover {
  background: #2563eb;
}

/* ==========================================================================
   Scripture Reader Area
   ========================================================================== */
.scripture-reader-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 32px 38px;
  box-shadow: var(--shadow-sm);
  min-height: 480px;
}

.reader-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.chapter-title-cluster {
  display: flex;
  align-items: center;
  gap: 16px;
}

.reader-book-circle-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--accent-blue-light);
  color: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.reader-book-circle-icon svg {
  width: 22px;
  height: 22px;
}

.chapter-primary-heading {
  font-size: 1.85rem;
  font-weight: 700;
  color: var(--text-navy);
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.chapter-secondary-subheading {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 3px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.subheading-bullet {
  color: var(--text-light);
}

.reader-meta-badges {
  display: flex;
  align-items: center;
  gap: 8px;
}

.badge-navy-translation {
  background: #0f1e36;
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  letter-spacing: 0.05em;
}

[data-theme="dark"] .badge-navy-translation {
  background: #1e3a8a;
}

.badge-verse-total {
  background: var(--bg-subtle);
  color: var(--text-muted);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: var(--radius-full);
}

/* Verses List */
.reader-verses-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.verse-row-container {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  transition: var(--transition);
  position: relative;
}

.verse-row-container:hover {
  background: var(--bg-hover);
}

.verse-row-container.bookmarked-row {
  background: rgba(184, 134, 11, 0.05);
  border-left: 3px solid var(--accent-gold);
}

.verse-badge-col {
  padding-top: 2px;
  flex-shrink: 0;
}

.verse-number-circle {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-blue-light);
  color: var(--accent-blue);
  font-size: 0.82rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.verse-text-col {
  flex: 1;
}

.verse-text-content {
  font-size: var(--verse-font-size, 18px);
  color: var(--text-secondary);
  line-height: 1.85;
}

/* Verse Controls (Search, Bookmark, Copy) */
.verse-controls-col {
  display: flex;
  align-items: center;
  gap: 4px;
  opacity: 0;
  transition: opacity 0.15s ease;
  flex-shrink: 0;
  padding-top: 2px;
}

.verse-row-container:hover .verse-controls-col,
.verse-row-container:focus-within .verse-controls-col {
  opacity: 1;
}

.btn-verse-control {
  width: 30px;
  height: 30px;
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  box-shadow: var(--shadow-xs);
}

.btn-verse-control svg {
  width: 15px;
  height: 15px;
}

.btn-verse-control:hover {
  color: var(--accent-blue);
  border-color: #cbd5e1;
  background: var(--bg-hover);
}

.btn-verse-bookmark.bookmarked {
  color: var(--accent-gold);
}

/* ==========================================================================
   Search, Bookmarks, and Offline Panels
   ========================================================================== */
.search-panel-card,
.bookmarks-panel-card,
.offline-panel-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 32px 38px;
  box-shadow: var(--shadow-sm);
  min-height: 480px;
}

/* Search Form */
.search-form-row {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.search-input-field-wrap {
  flex: 1;
  min-width: 260px;
  display: flex;
  align-items: center;
  background: var(--bg-page);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 0 14px;
  position: relative;
}

.search-lens-icon {
  margin-right: 8px;
  color: var(--text-muted);
}

.search-text-input {
  width: 100%;
  border: none;
  background: transparent;
  padding: 10px 0;
  font-size: 0.92rem;
  color: var(--text-secondary);
  outline: none;
}

.btn-clear-search-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  padding: 4px;
}

.search-testament-select select {
  padding: 10px 30px 10px 12px;
  border-radius: var(--radius-md);
}

.btn-search-action {
  background: #0f1e36;
  color: #ffffff;
  padding: 10px 24px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  transition: var(--transition);
}

.btn-search-action:hover {
  background: #1e293b;
}

.search-meta-bar {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 16px;
  font-weight: 500;
}

.search-cards-grid {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.search-result-card {
  padding: 18px 20px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-page);
  transition: var(--transition);
}

.search-result-card:hover {
  border-color: #cbd5e1;
  background: var(--bg-hover);
}

.search-result-header {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 8px;
}

.result-ref-title {
  font-weight: 700;
  color: var(--text-navy);
  font-size: 1.05rem;
}

.result-telugu-ref {
  color: var(--text-muted);
  font-size: 0.85rem;
}

.result-trans-badge {
  margin-left: auto;
  background: var(--bg-subtle);
  color: var(--text-muted);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.result-verse-text {
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 12px;
}

.btn-result-navigate {
  color: var(--accent-blue);
  font-size: 0.85rem;
  font-weight: 600;
}

/* Bookmarks List */
.bookmarks-header-row {
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.bookmarks-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-navy);
}

.bookmarks-subtitle {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.bookmarks-empty-state {
  text-align: center;
  padding: 60px 20px;
  color: var(--text-muted);
}

.empty-icon-box {
  font-size: 2.5rem;
  margin-bottom: 12px;
}

.bookmarks-list-grid {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.bookmark-item-card {
  padding: 20px 22px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--bg-page);
}

.bookmark-card-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.bookmark-ref-names {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.bookmark-ref-en {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-navy);
}

.bookmark-ref-te {
