  color: var(--accent-blue);
}

.offline-progress-track {
  width: 100%;
  height: 6px;
  background: var(--border-subtle);
  border-radius: 9999px;
  overflow: hidden;
}

.offline-progress-fill {
  height: 100%;
  background: var(--accent-green);
